import{_ as e,c as t,o as a,a4 as o}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q8：useState 使用细节及原理","description":"","frontmatter":{},"headers":[],"relativePath":"react/q8.md","filePath":"react/q8.md","lastUpdated":null}'),s={name:"react/q8.md"},c=o('<h1 id="q8-usestate-使用细节及原理" tabindex="-1">Q8：<code>useState</code> 使用细节及原理 <a class="header-anchor" href="#q8-usestate-使用细节及原理" aria-label="Permalink to &quot;Q8：`useState` 使用细节及原理&quot;">​</a></h1><p><code>const [state, setState] = useState(initialState);</code></p><ul><li><strong>惰性初始化</strong>：若初始状态计算昂贵，可传函数 <code>useState(() =&gt; compute())</code>，它仅在首次渲染执行。</li><li><strong>更新方式</strong>：<code>setState</code> 可传新值或更新函数 <code>(prevState) =&gt; newState</code>。React 使用 <code>Object.is</code> 比较，值相同时跳过渲染。</li><li><strong>批处理</strong>：React 18 之前仅在事件处理中批处理，React 18 后自动批处理扩大到 setTimeout、原生事件等场景。</li><li><strong>闭包陷阱</strong>：在异步操作中直接使用 state 可能拿到旧值，应使用函数式更新 <code>setState(prev =&gt; prev + 1)</code> 或用 <code>useRef</code> 保存最新值。</li></ul>',3),r=[c];function d(n,i,l,_,u,p){return a(),t("div",null,r)}const m=e(s,[["render",d]]);export{g as __pageData,m as default};
